messages.body_plain:
S-News Users,

 

The program below works but not like 
I would like though. How to return, as bestrow, the index for which delta is 
minimum?

 

findbestrow <- function(mat) 
{
 rows   <- 
dim(mat)[1];
        for (index in 
1:(rows-1)) 
{
                
newmat <- 
rowcombine(mat,index);
                
delta  <- 
chisq.test(newmat)$statistic;
                
print(paste("index=",index,"delta=",delta));
                        
bestrow         <- 
index;
                        
bestdelta       <- 
min(delta);
                        
bestmat   <- 
newmat;
                        
print(paste("find best row has a best so far: 
",bestrow,bestdelta));
                 
}       

        list(row=bestrow, 
delta=bestdelta, newmat=bestmat);     

        
}       

rowsolution <- 
findbestrow(mat);
rowsolution;
